161	/* Squash on press: 0.97 and back. Colours keep the chip timing. */
162	.press {
163	  transition:
164	    scale var(--dur-chip) var(--ease-enter),
165	    color var(--dur-chip) var(--ease-enter),
166	    background-color var(--dur-chip) var(--ease-enter),
167	    border-color var(--dur-chip) var(--ease-enter),
168	    opacity var(--dur-chip) var(--ease-enter);
169	}
170	.press:not(:disabled):active {
171	  scale: 0.97;
172	  transition-duration: 90ms;
173	}
174	
175	/* Small chips and tiles that change state. */
176	.chip-t {
177	  transition:
178	    color var(--dur-chip) var(--ease-enter),
179	    background-color var(--dur-chip) var(--ease-enter),
180	    border-color var(--dur-chip) var(--ease-enter),
181	    box-shadow var(--dur-chip) var(--ease-enter),
182	    opacity var(--dur-chip) var(--ease-enter);
183	}
184	
185	/* Story windows. Rise on an arc (Y: enter, X: arc), exit quicker and softer. */
186	.win {
187	  opacity: 0;
188	  transform: translateY(28px);
189	  translate: -14px 0;
190	  transition:
191	    opacity 300ms var(--ease-exit),
192	    transform 300ms var(--ease-exit),
193	    translate 300ms var(--ease-exit);
194	}
195	.win[data-in="true"] {
196	  opacity: 1;
197	  transform: none;
198	  translate: none;
199	  transition:
200	    opacity var(--dur-window) var(--ease-enter),
201	    transform var(--dur-window) var(--ease-enter),
202	    translate var(--dur-window) var(--ease-arc);
203	}
204	/* Staging: while another window acts, this one steps back. */
205	.win[data-in="true"][data-dim="true"] {
206	  opacity: 0.55;
207	  transition:
208	    opacity 300ms var(--ease-exit),
209	    transform var(--dur-window) var(--ease-enter),
210	    translate var(--dur-window) var(--ease-arc);
211	}
212	/* The title bar leads; the body follows about 120 ms behind it. */
213	.win-body {
214	  opacity: 0;
215	  transition: opacity 180ms var(--ease-exit);
216	}
217	.win[data-in="true"] .win-body {
218	  opacity: 1;
219	  transition: opacity 450ms var(--ease-enter) 120ms;
220	}
221	.story-group {
222	  transition: opacity 350ms var(--ease-exit);
223	}
224	.story-group[data-leaving="true"] {
225	  opacity: 0;
226	}
227	
228	/* Scroll reveal: the same rise, driven by lib/inview.ts. --rd is the follow-through delay. */
229	/* The sideways offset is capped at the page gutter (1rem, 1.5rem from 40rem), so an unrevealed
230	   full-width block never sticks out past the viewport and makes the page scroll sideways. */
231	.reveal {
232	  --reach: 1rem;
233	  opacity: 0;
234	  transform: translateY(28px);
235	  translate: clamp(calc(-1 * var(--reach)), var(--rx, -12px), var(--reach)) 0;
236	  transition:
237	    opacity var(--dur-window) var(--ease-enter) var(--rd, 0s),
238	    transform var(--dur-window) var(--ease-enter) var(--rd, 0s),
239	    translate var(--dur-window) var(--ease-arc) var(--rd, 0s);
240	}
241	@media (min-width: 40rem) {
242	  .reveal { --reach: 1.5rem; }
243	}
244	.reveal[data-in="true"] {
245	  opacity: 1;
246	  transform: none;
247	  translate: none;
248	}
249	
250	/* Strokes that draw themselves (pathLength="1" on the path). */
251	.draw {
252	  stroke-dasharray: 1;
253	  stroke-dashoffset: 1;
254	  transition: stroke-dashoffset var(--draw-ms, 800ms) var(--ease-enter) var(--rd, 0s);
255	}
256	[data-in="true"] .draw {
257	  stroke-dashoffset: 0;
258	}
259	
260	/* Things that arrive: a 2 px overshoot, then rest. --i staggers siblings by 45 ms. */
261	.settle {
262	  animation: settle 180ms var(--ease-enter) both;
263	  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
264	}
265	@keyframes settle {
266	  0% { opacity: 0; transform: translateY(6px); }
267	  65% { opacity: 1; transform: translateY(-2px); }
268	  100% { opacity: 1; transform: none; }
269	}
270	
271	/* Follow-through for things already on screen: a 2 px nudge that settles, staggered by --i. */
272	.follow {
273	  animation: follow 220ms var(--ease-enter) backwards;
274	  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
275	}
276	@keyframes follow {
277	  0% { transform: none; }
278	  40% { transform: translateY(2px); }
279	  100% { transform: none; }
280	}
281	
282	/* Exaggeration, three places only. */
283	/* 1. A failing step: one red flash, 300 ms. */
284	.flash-bad {
285	  animation: flash-bad 300ms var(--ease-exit) both;
286	}
287	@keyframes flash-bad {
288	  0% { background-color: color-mix(in srgb, var(--broken) 24%, transparent); }
289	  100% { background-color: transparent; }
290	}
291	/* 2. The winning fix: one quick lemon sweep. */
292	.sweep {
293	  background-image: linear-gradient(100deg, transparent 0%, color-mix(in srgb, var(--evidence) 75%, transparent) 45%, transparent 90%);
294	  background-size: 250% 100%;
295	  background-repeat: no-repeat;
296	  animation: sweep 520ms var(--ease-enter) both;
297	}
298	@keyframes sweep {
299	  from { background-position: 100% 0; }
300	  to { background-position: 0 0; }
301	}
302	/* 3. The verdict: a single overshoot to 1.03. */
303	.verdict-land {
304	  transform-origin: left center;
305	  animation: verdict-land 420ms var(--ease-enter) both;
306	}
307	@keyframes verdict-land {
308	  0% { opacity: 0; transform: scale(0.94); }
309	  55% { opacity: 1; transform: scale(1.03); }
310	  100% { opacity: 1; transform: scale(1); }
311	}
312	/* The one flourish when a run verifies: the lifted-r wordmark rises 4 px and settles. */
313	.lift {
314	  animation: lift 520ms var(--ease-enter);
315	}
316	@keyframes lift {
317	  0% { translate: 0 0; }
318	  40% { translate: 0 -4px; }
319	  100% { translate: 0 0; }
320	}
321	
322	/* Route change: the new page rises in. */
323	.route-enter {
324	  animation: route-in 260ms var(--ease-enter) backwards;
325	}
326	@keyframes route-in {
327	  from { opacity: 0; transform: translateY(10px); }
328	}
329	
330	/* Theme icon swap. */
331	.icon-turn {
332	  animation: icon-turn 240ms var(--ease-enter) backwards;
333	}
334	@keyframes icon-turn {
335	  from { opacity: 0; rotate: -50deg; scale: 0.6; }
336	}
337	
338	/* Secondary actions: they pause while a primary beat plays (lib/beat.ts sets data-beat). */
339	.dot-pulse {
340	  animation: dot-pulse 2.4s ease-in-out infinite;
341	}
342	@keyframes dot-pulse {
343	  50% { opacity: 0.4; }
344	}
345	[data-beat="on"] .dot-pulse {
346	  animation-play-state: paused;
347	}
348	
349	/* The orb holds still unless the model is thinking. */
350	.orb-still .siri-orb::before,
351	.orb-still .siri-orb-sheen {
352	  animation-play-state: paused !important;
353	}
354	
355	/* Text cursor: solid while text is arriving, blinking only while it waits. */
356	.stream-cursor {
357	  display: inline-block;
358	  width: 0.5em;
359	  height: 1.05em;
360	  margin-left: 2px;
361	  vertical-align: -0.18em;
362	  background: currentColor;
363	}
364	.stream-cursor.blink {
365	  animation: stream-blink var(--blink) steps(1) infinite;
366	}
367	@keyframes stream-blink {
368	  50% { opacity: 0; }
369	}
370	
371	@media (prefers-reduced-motion: reduce) {
372	  html { scroll-behavior: auto; }
373	  .stream-cursor.blink { animation: none; }
374	  *, *::before, *::after {
375	    animation-duration: 0.001ms !important;
376	    animation-iteration-count: 1 !important;
377	    transition-duration: 0.001ms !important;
378	  }
379	}
