@import "tailwindcss";
@import "tw-animate-css";
@import "@fontsource-variable/source-sans-3";
@import "@fontsource/source-code-pro/400.css";
@import "@fontsource/source-code-pro/600.css";

@custom-variant dark (&:is([data-theme="dark"] *));

/*
 * Resurgo brand: Daylight lab (docs/reference/tokens.css, verbatim).
 * Light by default; dark via [data-theme="dark"] or the system preference
 * unless the visitor has picked light.
 */
:root {
  --canvas: #F3F6FA; --panel: #FFFFFF; --muted: #EAEFF5;
  --ink: #0F1720; --ink-2: #2A3441; --secondary: #55606E;
  --hairline: #DCE3EC; --control: #C6D0DC;
  --accent: #2F6BFF;          /* art, focus rings, large accents */
  --accent-strong: #2459E8;   /* buttons with white text (5.7:1), links */
  --on-accent: #FFFFFF;
  --evidence: #E6FB63; --on-evidence: #0F1720;   /* highlighter for fixes and proof */
  --runs: #127A4A;  --runs-soft: #E2F3EA;
  --gaps: #8A6400;  --gaps-soft: #FBF1D2;
  --broken: #BE3A2E; --broken-soft: #FBE7E3;
  --checking: #2459E8; --checking-soft: #E7EEFF;
  --terminal: #FFFFFF; --terminal-ink: #0F1720;
  color-scheme: light;
}
:root[data-theme="dark"] {
  --canvas: #0E1420; --panel: #151D2B; --muted: #1C2635;
  --ink: #EEF2F7; --ink-2: #CDD5E0; --secondary: #9AA6B5;
  --hairline: #263244; --control: #33415A;
  --accent: #6E98FF; --accent-strong: #6E98FF; --on-accent: #0E1420;
  --evidence: #D9F24A; --on-evidence: #0F1720;
  --runs: #4FD08C;  --runs-soft: rgba(79,208,140,.14);
  --gaps: #F2CC60;  --gaps-soft: rgba(242,204,96,.14);
  --broken: #FF8A78; --broken-soft: rgba(255,138,120,.14);
  --checking: #8AAEFF; --checking-soft: rgba(138,174,255,.14);
  --terminal: #121A27; --terminal-ink: #EEF2F7;
  color-scheme: dark;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --canvas: #0E1420; --panel: #151D2B; --muted: #1C2635;
    --ink: #EEF2F7; --ink-2: #CDD5E0; --secondary: #9AA6B5;
    --hairline: #263244; --control: #33415A;
    --accent: #6E98FF; --accent-strong: #6E98FF; --on-accent: #0E1420;
    --evidence: #D9F24A; --on-evidence: #0F1720;
    --runs: #4FD08C;  --runs-soft: rgba(79,208,140,.14);
    --gaps: #F2CC60;  --gaps-soft: rgba(242,204,96,.14);
    --broken: #FF8A78; --broken-soft: rgba(255,138,120,.14);
    --checking: #8AAEFF; --checking-soft: rgba(138,174,255,.14);
    --terminal: #121A27; --terminal-ink: #EEF2F7;
    color-scheme: dark;
  }
}

:root {
  --radius: 0.5rem;
}

@theme inline {
  /* Brand names. */
  --color-canvas: var(--canvas);
  --color-panel: var(--panel);
  --color-muted: var(--muted);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-secondary: var(--secondary);
  --color-hairline: var(--hairline);
  --color-control: var(--control);
  --color-accent: var(--accent);
  --color-accent-strong: var(--accent-strong);
  --color-on-accent: var(--on-accent);
  --color-evidence: var(--evidence);
  --color-on-evidence: var(--on-evidence);
  --color-runs: var(--runs);
  --color-runs-soft: var(--runs-soft);
  --color-gaps: var(--gaps);
  --color-gaps-soft: var(--gaps-soft);
  --color-broken: var(--broken);
  --color-broken-soft: var(--broken-soft);
  --color-checking: var(--checking);
  --color-checking-soft: var(--checking-soft);
  --color-terminal: var(--terminal);
  --color-terminal-ink: var(--terminal-ink);
  /* Names the shadcn and SmoothUI components were written against. */
  --color-background: var(--canvas);
  --color-foreground: var(--ink);
  --color-card: var(--panel);
  --color-card-foreground: var(--ink);
  --color-muted-foreground: var(--secondary);
  --color-border: var(--hairline);
  --color-ring: var(--accent);
  --color-destructive: var(--broken);
  --color-highlight: var(--evidence);
  --color-highlight-foreground: var(--on-evidence);
  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --font-sans: "Source Sans 3 Variable", "Source Sans 3", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Source Code Pro", ui-monospace, "SFMono-Regular", Menlo, monospace;
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

* {
  border-color: var(--hairline);
}

:focus-visible {
  outline: 2px solid var(--accent-strong);
  outline-offset: 2px;
  border-radius: 4px;
}

::selection {
  background: var(--evidence);
  color: var(--on-evidence);
}

/*
 * Motion (docs/ANIMATION.md). One entrance easing for everything that arrives; exits are gentler.
 * lib/ease.ts reads --ease-enter for the JS animations, so this is the only place it is defined.
 * Only timers, progress and spinner rotation are linear.
 */
:root {
  --ease-enter: cubic-bezier(.22, 1, .36, 1);
  --ease-exit: cubic-bezier(.4, 0, .6, 1);
  --ease-arc: cubic-bezier(.45, 0, .2, 1);   /* X of an arc; Y uses --ease-enter */
  --dur-chip: 150ms;                          /* chips and small controls: 120-180 ms */
  --dur-window: 600ms;                        /* windows: 450-650 ms */
  --blink: 400ms;                             /* two blinks = 800 ms of anticipation before typing */
}

/* Theme switch: colours cross-fade for a moment instead of snapping. Set by lib/theme.ts. */
@media (prefers-reduced-motion: no-preference) {
  .theme-fade,
  .theme-fade *,
  .theme-fade *::before,
  .theme-fade *::after {
    transition:
      background-color 240ms var(--ease-enter),
      color 240ms var(--ease-enter),
      border-color 240ms var(--ease-enter),
      fill 240ms var(--ease-enter),
      stroke 240ms var(--ease-enter);
  }
}

/* Squash on press: 0.97 and back. Colours keep the chip timing. */
.press {
  transition:
    scale var(--dur-chip) var(--ease-enter),
    color var(--dur-chip) var(--ease-enter),
    background-color var(--dur-chip) var(--ease-enter),
    border-color var(--dur-chip) var(--ease-enter),
    opacity var(--dur-chip) var(--ease-enter);
}
.press:not(:disabled):active {
  scale: 0.97;
  transition-duration: 90ms;
}

/* Small chips and tiles that change state. */
.chip-t {
  transition:
    color var(--dur-chip) var(--ease-enter),
    background-color var(--dur-chip) var(--ease-enter),
    border-color var(--dur-chip) var(--ease-enter),
    box-shadow var(--dur-chip) var(--ease-enter),
    opacity var(--dur-chip) var(--ease-enter);
}

/* Story windows. Rise on an arc (Y: enter, X: arc), exit quicker and softer. */
.win {
  opacity: 0;
  transform: translateY(28px);
  translate: -14px 0;
  transition:
    opacity 300ms var(--ease-exit),
    transform 300ms var(--ease-exit),
    translate 300ms var(--ease-exit);
}
.win[data-in="true"] {
  opacity: 1;
  transform: none;
  translate: none;
  transition:
    opacity var(--dur-window) var(--ease-enter),
    transform var(--dur-window) var(--ease-enter),
    translate var(--dur-window) var(--ease-arc);
}
/* Staging: while another window acts, this one steps back. */
.win[data-in="true"][data-dim="true"] {
  opacity: 0.55;
  transition:
    opacity 300ms var(--ease-exit),
    transform var(--dur-window) var(--ease-enter),
    translate var(--dur-window) var(--ease-arc);
}
/* The title bar leads; the body follows about 120 ms behind it. */
.win-body {
  opacity: 0;
  transition: opacity 180ms var(--ease-exit);
}
.win[data-in="true"] .win-body {
  opacity: 1;
  transition: opacity 450ms var(--ease-enter) 120ms;
}
.story-group {
  transition: opacity 350ms var(--ease-exit);
}
.story-group[data-leaving="true"] {
  opacity: 0;
}

/* Scroll reveal: the same rise, driven by lib/inview.ts. --rd is the follow-through delay. */
/* The sideways offset is capped at the page gutter (1rem, 1.5rem from 40rem), so an unrevealed
   full-width block never sticks out past the viewport and makes the page scroll sideways. */
.reveal {
  --reach: 1rem;
  opacity: 0;
  transform: translateY(28px);
  translate: clamp(calc(-1 * var(--reach)), var(--rx, -12px), var(--reach)) 0;
  transition:
    opacity var(--dur-window) var(--ease-enter) var(--rd, 0s),
    transform var(--dur-window) var(--ease-enter) var(--rd, 0s),
    translate var(--dur-window) var(--ease-arc) var(--rd, 0s);
}
@media (min-width: 40rem) {
  .reveal { --reach: 1.5rem; }
}
.reveal[data-in="true"] {
  opacity: 1;
  transform: none;
  translate: none;
}

/* Strokes that draw themselves (pathLength="1" on the path). */
.draw {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset var(--draw-ms, 800ms) var(--ease-enter) var(--rd, 0s);
}
[data-in="true"] .draw {
  stroke-dashoffset: 0;
}

/* Things that arrive: a 2 px overshoot, then rest. --i staggers siblings by 45 ms. */
.settle {
  animation: settle 180ms var(--ease-enter) both;
  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
}
@keyframes settle {
  0% { opacity: 0; transform: translateY(6px); }
  65% { opacity: 1; transform: translateY(-2px); }
  100% { opacity: 1; transform: none; }
}

/* Follow-through for things already on screen: a 2 px nudge that settles, staggered by --i. */
.follow {
  animation: follow 220ms var(--ease-enter) backwards;
  animation-delay: calc(var(--d, 0ms) + var(--i, 0) * 45ms);
}
@keyframes follow {
  0% { transform: none; }
  40% { transform: translateY(2px); }
  100% { transform: none; }
}

/* Exaggeration, three places only. */
/* 1. A failing step: one red flash, 300 ms. */
.flash-bad {
  animation: flash-bad 300ms var(--ease-exit) both;
}
@keyframes flash-bad {
  0% { background-color: color-mix(in srgb, var(--broken) 24%, transparent); }
  100% { background-color: transparent; }
}
/* 2. The winning fix: one quick lemon sweep. */
.sweep {
  background-image: linear-gradient(100deg, transparent 0%, color-mix(in srgb, var(--evidence) 75%, transparent) 45%, transparent 90%);
  background-size: 250% 100%;
  background-repeat: no-repeat;
  animation: sweep 520ms var(--ease-enter) both;
}
@keyframes sweep {
  from { background-position: 100% 0; }
  to { background-position: 0 0; }
}
/* 3. The verdict: a single overshoot to 1.03. */
.verdict-land {
  transform-origin: left center;
  animation: verdict-land 420ms var(--ease-enter) both;
}
@keyframes verdict-land {
  0% { opacity: 0; transform: scale(0.94); }
  55% { opacity: 1; transform: scale(1.03); }
  100% { opacity: 1; transform: scale(1); }
}
/* The one flourish when a run verifies: the lifted-r wordmark rises 4 px and settles. */
.lift {
  animation: lift 520ms var(--ease-enter);
}
@keyframes lift {
  0% { translate: 0 0; }
  40% { translate: 0 -4px; }
  100% { translate: 0 0; }
}

/* Route change: the new page rises in. */
.route-enter {
  animation: route-in 260ms var(--ease-enter) backwards;
}
@keyframes route-in {
  from { opacity: 0; transform: translateY(10px); }
}

/* Theme icon swap. */
.icon-turn {
  animation: icon-turn 240ms var(--ease-enter) backwards;
}
@keyframes icon-turn {
  from { opacity: 0; rotate: -50deg; scale: 0.6; }
}

/* Secondary actions: they pause while a primary beat plays (lib/beat.ts sets data-beat). */
.dot-pulse {
  animation: dot-pulse 2.4s ease-in-out infinite;
}
@keyframes dot-pulse {
  50% { opacity: 0.4; }
}
[data-beat="on"] .dot-pulse {
  animation-play-state: paused;
}

/* The orb holds still unless the model is thinking. */
.orb-still .siri-orb::before,
.orb-still .siri-orb-sheen {
  animation-play-state: paused !important;
}

/* Text cursor: solid while text is arriving, blinking only while it waits. */
.stream-cursor {
  display: inline-block;
  width: 0.5em;
  height: 1.05em;
  margin-left: 2px;
  vertical-align: -0.18em;
  background: currentColor;
}
.stream-cursor.blink {
  animation: stream-blink var(--blink) steps(1) infinite;
}
@keyframes stream-blink {
  50% { opacity: 0; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .stream-cursor.blink { animation: none; }
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

