160	const STAGE_LABEL: Record<string, string> = {
161	  clone: "Fresh clone at the pinned commit",
162	  toolchain: "Prepare the toolchain",
163	  detect: "Detect the package manager",
164	  env: "Fill .env with dummy values",
165	  install: "Install dependencies",
166	  build: "Build",
167	  test: "Run tests",
168	  serve: "Start it and probe the port",
169	};
