171	/** One AI Diff block per file in a unified patch. */
172	export function parsePatch(patch: string): { title: string; lines: AIDiffLine[] }[] {
173	  const files: { title: string; lines: AIDiffLine[] }[] = [];
174	  let cur: { title: string; lines: AIDiffLine[] } | null = null;
175	  for (const raw of patch.replace(/\n$/, "").split("\n")) {
176	    if (raw.startsWith("diff --git ")) {
177	      cur = { title: raw.replace(/^diff --git a\/(.*) b\/.*$/, "$1"), lines: [] };
178	      files.push(cur);
179	    } else if (!cur || /^(index |--- |\+\+\+ |new file|deleted file|old mode|new mode|similarity|rename )/.test(raw)) {
180	      continue;
181	    } else if (raw.startsWith("@@")) {
182	      cur.lines.push({ kind: "context", content: raw });
183	    } else if (raw.startsWith("+")) {
184	      cur.lines.push({ kind: "added", content: raw.slice(1) });
185	    } else if (raw.startsWith("-")) {
186	      cur.lines.push({ kind: "removed", content: raw.slice(1) });
187	    } else if (raw.length || cur.lines.length) {
188	      cur.lines.push({ kind: "context", content: raw.slice(1) });
189	    }
190	  }
191	  return files.filter((f) => f.lines.length);
192	}
193	
194	/** Strip pnpm/terminal noise so output tails read cleanly. */
195	export const cleanLine = (l: string) => l.replace(/\u001b\[[0-9;]*m/g, "");
