6	
7	/** Status as a word plus a glyph, never colour alone. */
8	export function StatusBadge({ status, className }: { status: string; className?: string }) {
9	  const m = statusMeta(status);
10	  return (
11	    <span
12	      className={cn(
13	        "inline-flex items-center gap-1.5 rounded-full border border-transparent px-2.5 py-0.5 text-sm font-semibold",
14	        m.tone,
15	        className,
16	      )}
17	    >
18	      <span aria-hidden className="font-mono">{m.glyph}</span>
19	      {m.word}
20	    </span>
21	  );
22	}
23	
24	/**
25	 * Scroll reveal: the shared rise on a slight arc (Y: enter easing, X: arc easing). `delay` is the
26	 * follow-through of a sibling, in seconds. Plain content under reduced motion (see .reveal in index.css).
27	 */
28	export function Reveal({
29	  children,
30	  className,
31	  delay = 0,
32	  x = 0,
33	}: {
34	  children: ReactNode;
35	  className?: string;
36	  delay?: number;
37	  x?: number;
38	}) {
